builder.Services.AddAuthentication(CookieAuthenticationDefaults.AuthenticationScheme)
    .AddCookie(options =>
    {
        options.LoginPath = "/Account/Login";
        options.AccessDeniedPath = "/Account/AccessDenied";
        options.ExpireTimeSpan = TimeSpan.FromHours(8);
        options.SlidingExpiration = true;
    });

var app = builder.Build();
app.UseHttpsRedirection();
app.UseStaticFiles();
app.UseRouting();
app.UseAuthentication(); // must come before UseAuthorization
app.UseAuthorization();
app.MapControllers();
app.Run();

// Require authentication for all actions in this controller
[Authorize]
public class DashboardController : Controller
{
    public IActionResult Index() => View();
}

// Allow anonymous access to a specific action
[Authorize]
public class ProductsController : Controller
{
    [AllowAnonymous]
    public IActionResult List() => View();

    // Require Admin role for this action
    [Authorize(Roles = "Admin")]
    public IActionResult Manage() => View();

    // Require a specific policy
    [Authorize(Policy = "RequireEmailVerified")]
    public IActionResult Settings() => View();
}

[Authorize]
public class AccountController : Controller
{
    public IActionResult Profile()
    {
        var userId = User.FindFirst(ClaimTypes.NameIdentifier)?.Value;
        var email = User.FindFirst(ClaimTypes.Email)?.Value;
        var name = User.FindFirst(ClaimTypes.Name)?.Value;
        var roles = User.FindAll(ClaimTypes.Role).Select(c => c.Value).ToList();

        ViewBag.UserId = userId;
        ViewBag.Email = email;
        ViewBag.Name = name;
        ViewBag.Roles = roles;
        return View();
    }
}
